#ifndef ACTIONEVENT_H
#define ACTIONEVENT_H

#include "baseevent.h"
#include <string>
#include <iostream>

namespace rmcommon {

/*!
 * \class event generated by the resource management policy when an action
 * has to be performed by the external dispatcher (e.g. moving a task away
 * from a compromised node).
 * \p
 * printOnOstream() writes the JSON object that is delivered as is by
 * GET /actions, so the field names must match the ones read by the dispatcher:
 * \code
 * {"action":"migrate","task":"T1","compromised":"iotsim-edge-worker-1","to":"iotsim-edge-worker-2"}
 * \endcode
 * "to" is empty for actions that do not need a destination (e.g. "kill").
 */
class ActionEvent : public BaseEvent {
public:
    /*! Actions known by the dispatcher */
    static constexpr const char *MIGRATE = "migrate";
    static constexpr const char *KILL = "kill";
    static constexpr const char *LAUNCH = "launch";

private:
    std::string action_;
    std::string task_;
    std::string compromised_;
    std::string to_;

    /*! Writes a string in JSON format, escaping quotes and backslashes */
    static void printString(std::ostream &os, const std::string &s) {
        os << '"';
        for (char c : s) {
            if (c == '"' || c == '\\') {
                os << '\\';
            }
            os << c;
        }
        os << '"';
    }

public:
    /*!
     * \param action one of MIGRATE, KILL, LAUNCH
     * \param task identifier of the task (e.g. "T1")
     * \param compromised name of the compromised node that triggered the action
     * \param to name of the destination node (empty if not needed)
     */
    ActionEvent(const std::string &action,
                const std::string &task,
                const std::string &compromised,
                const std::string &to = "") :
        BaseEvent("ActionEvent"),
        action_(action),
        task_(task),
        compromised_(compromised),
        to_(to) {}

    const std::string &getAction() const {
        return action_;
    }

    const std::string &getTask() const {
        return task_;
    }

    const std::string &getCompromised() const {
        return compromised_;
    }

    const std::string &getTo() const {
        return to_;
    }

    void printOnOstream(std::ostream &os) const override {
        os << "{\"action\":";
        printString(os, action_);
        os << ",\"task\":";
        printString(os, task_);
        os << ",\"compromised\":";
        printString(os, compromised_);
        if (!to_.empty()) {
            os << ",\"to\":";
            printString(os, to_);
        }
        os << "}";
    }
};

}   // namespace rmcommon

#endif // ACTIONEVENT_H

